import{_ as i,A as E,o as e,c as h,O as r,b as s,w as a,Z as n,E as d,a as o}from"./chunks/framework.2c2d5a61.js";const D=JSON.parse('{"title":"高并发系统设计","description":"","frontmatter":{},"headers":[],"relativePath":"backend/系统设计/高并发系统设计.md","filePath":"backend/系统设计/高并发系统设计.md","lastUpdated":1788941422000}'),p={name:"backend/系统设计/高并发系统设计.md"};function B(u,t,c,b,A,g){const l=E("Mermaid");return e(),h("div",null,[t[4]||(t[4]=r(`<h1 id="高并发系统设计" tabindex="-1">高并发系统设计 <a class="header-anchor" href="#高并发系统设计" aria-label="Permalink to &quot;高并发系统设计&quot;">​</a></h1><blockquote><p>从容量评估到分层防护、从缓存与异步化到隔离熔断降级限流，给出一套&quot;先量化、再分层、后取舍&quot;的高并发系统设计方法论，附通用 8 步设计法。</p></blockquote><hr><h2 id="一、容量评估" tabindex="-1">一、容量评估 <a class="header-anchor" href="#一、容量评估" aria-label="Permalink to &quot;一、容量评估&quot;">​</a></h2><h3 id="_1-1-核心指标定义" tabindex="-1">1.1 核心指标定义 <a class="header-anchor" href="#_1-1-核心指标定义" aria-label="Permalink to &quot;1.1 核心指标定义&quot;">​</a></h3><table><thead><tr><th>指标</th><th>定义</th><th>说明</th></tr></thead><tbody><tr><td>QPS</td><td>每秒查询/请求数</td><td>互联网系统最常用</td></tr><tr><td>TPS</td><td>每秒事务数</td><td>一个完整业务事务（如下单），事务可含多次请求</td></tr><tr><td>RT</td><td>响应时间（平均/TP99/P99）</td><td>单次请求耗时，P99 比平均值更能反映尾部体验</td></tr><tr><td>并发数</td><td>系统中同时处理的请求数</td><td>由 Little 定律：并发数 ≈ QPS × RT</td></tr><tr><td>吞吐量</td><td>单位时间成功处理的请求数</td><td>系统能力的上限表达</td></tr></tbody></table><p>Little 定律是容量估算的锚：<code>并发线程数 = QPS × RT(秒)</code>。例如 QPS 2000、RT 0.1s，则并发约 200，可据此决定线程池大小与实例数。</p><h3 id="_1-2-容量估算方法" tabindex="-1">1.2 容量估算方法 <a class="header-anchor" href="#_1-2-容量估算方法" aria-label="Permalink to &quot;1.2 容量估算方法&quot;">​</a></h3><p>估算公式链：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">PV（日页面访问量）</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 日请求量 ≈ PV × 单页平均请求数（一般 5~10）</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 平均 QPS = 日请求量 / 86400</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 峰值 QPS = 平均 QPS × 峰值因子</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 需要的实例数 = 峰值 QPS / 单实例可支撑 QPS（预留 30% 余量）</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">PV（日页面访问量）</span></span>
<span class="line"><span style="color:#24292e;">  → 日请求量 ≈ PV × 单页平均请求数（一般 5~10）</span></span>
<span class="line"><span style="color:#24292e;">  → 平均 QPS = 日请求量 / 86400</span></span>
<span class="line"><span style="color:#24292e;">  → 峰值 QPS = 平均 QPS × 峰值因子</span></span>
<span class="line"><span style="color:#24292e;">  → 需要的实例数 = 峰值 QPS / 单实例可支撑 QPS（预留 30% 余量）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>单实例可支撑 QPS 的经验量级（参考，需压测校准）：</p><table><thead><tr><th>组件</th><th>单实例经验量级</th></tr></thead><tbody><tr><td>Nginx</td><td>数万 QPS</td></tr><tr><td>业务应用（Java，含 DB 往返）</td><td>数百~数千 QPS</td></tr><tr><td>Redis</td><td>5~10 万 QPS</td></tr><tr><td>MySQL（简单查询）</td><td>数千 QPS</td></tr><tr><td>MySQL（写，单机）</td><td>数百~千级 TPS</td></tr></tbody></table><h3 id="_1-3-峰值因子与业务特征" tabindex="-1">1.3 峰值因子与业务特征 <a class="header-anchor" href="#_1-3-峰值因子与业务特征" aria-label="Permalink to &quot;1.3 峰值因子与业务特征&quot;">​</a></h3><p>峰值因子不能套固定数字，按业务节奏定：</p><ul><li><strong>常态业务</strong>（后台管理系统）：峰值因子 3~5 倍；</li><li><strong>C 端日常</strong>：峰值因子 5~10 倍（晚高峰）；</li><li><strong>大促/热点事件</strong>：需按&quot;预热流量 + 活动预估&quot;单独建模，峰值因子可到 20~50 倍甚至更高（如秒杀）。</li></ul><p><strong>削峰思想</strong>出现在容量评估时就应开始：估算的不是&quot;扛住峰值&quot;而是&quot;峰值中多少必须实时处理、多少可以削峰异步&quot;（见第五章）。</p><h3 id="_1-4-压测目标与容量水位" tabindex="-1">1.4 压测目标与容量水位 <a class="header-anchor" href="#_1-4-压测目标与容量水位" aria-label="Permalink to &quot;1.4 压测目标与容量水位&quot;">​</a></h3><ul><li><strong>压测目标</strong>：找到系统的&quot;拐点&quot;——RT 开始陡增的 QPS（性能拐点）、以及错误率超过阈值的 QPS（容量上限），而不是压出最大数字；</li><li><strong>容量水位约定</strong>：生产运行水位不超过单机容量的 60%~70%，预留故障转移与突增缓冲；</li><li><strong>压测类型</strong>：单接口压测（定位瓶颈）→ 链路压测（全链路容量）→ 混合场景压测（贴近真实）→ 大促前全链路压测；</li><li><strong>数据要求</strong>：压测数据量必须贴近生产（大数据量下索引与缓存命中率才真实）。</li></ul><h3 id="_1-5-容量评估案例" tabindex="-1">1.5 容量评估案例 <a class="header-anchor" href="#_1-5-容量评估案例" aria-label="Permalink to &quot;1.5 容量评估案例&quot;">​</a></h3><p>一次大促预热场景：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">预估大促当日 PV = 2 亿（平时 3000 万）</span></span>
<span class="line"><span style="color:#e1e4e8;">单页请求数 = 8</span></span>
<span class="line"><span style="color:#e1e4e8;">日请求量 = 16 亿</span></span>
<span class="line"><span style="color:#e1e4e8;">平均 QPS = 16 亿 / 86400 ≈ 18500</span></span>
<span class="line"><span style="color:#e1e4e8;">峰值因子按活动节奏取 6（分时段放量）</span></span>
<span class="line"><span style="color:#e1e4e8;">峰值 QPS ≈ 111000</span></span>
<span class="line"><span style="color:#e1e4e8;">单实例业务应用按 1500 QPS 计</span></span>
<span class="line"><span style="color:#e1e4e8;">实例数 = 111000 / 1500 × 1.3（余量）≈ 96 台</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">预估大促当日 PV = 2 亿（平时 3000 万）</span></span>
<span class="line"><span style="color:#24292e;">单页请求数 = 8</span></span>
<span class="line"><span style="color:#24292e;">日请求量 = 16 亿</span></span>
<span class="line"><span style="color:#24292e;">平均 QPS = 16 亿 / 86400 ≈ 18500</span></span>
<span class="line"><span style="color:#24292e;">峰值因子按活动节奏取 6（分时段放量）</span></span>
<span class="line"><span style="color:#24292e;">峰值 QPS ≈ 111000</span></span>
<span class="line"><span style="color:#24292e;">单实例业务应用按 1500 QPS 计</span></span>
<span class="line"><span style="color:#24292e;">实例数 = 111000 / 1500 × 1.3（余量）≈ 96 台</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>该结果是&quot;架构能扛多少&quot;的输入，而非&quot;真的全实时扛&quot;——真正的解法是分层缓存 + 削峰异步把峰值压回一个数量级内（见第二章与第八章）。</p><hr><h2 id="二、分层防护总览" tabindex="-1">二、分层防护总览 <a class="header-anchor" href="#二、分层防护总览" aria-label="Permalink to &quot;二、分层防护总览&quot;">​</a></h2><h3 id="_2-1-六层防护架构" tabindex="-1">2.1 六层防护架构 <a class="header-anchor" href="#_2-1-六层防护架构" aria-label="Permalink to &quot;2.1 六层防护架构&quot;">​</a></h3><p>高并发系统的核心思想是<strong>流量分层消化，越靠前的层越廉价、越靠后的层越珍贵</strong>：</p>`,26)),(e(),s(n,null,{default:a(()=>[d(l,{id:"mermaid-225",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20U%5B%E7%94%A8%E6%88%B7%5D%20--%3E%20DNS%5BDNS%20%2B%20%E6%99%BA%E8%83%BD%E8%B0%83%E5%BA%A6%3Cbr%2F%3E%E5%B0%B1%E8%BF%91%E6%8E%A5%E5%85%A5%5D%0A%20%20%20%20DNS%20--%3E%20CDN%5BCDN%20%E9%9D%99%E6%80%81%E8%B5%84%E6%BA%90%3Cbr%2F%3E%E5%91%BD%E4%B8%AD%2090%25%2B%20%E9%9D%99%E6%80%81%E6%B5%81%E9%87%8F%5D%0A%20%20%20%20CDN%20--%3E%20GW%5B%E7%BD%91%E5%85%B3%E5%B1%82%3Cbr%2F%3E%E9%99%90%E6%B5%81%2F%E9%89%B4%E6%9D%83%2F%E8%B7%AF%E7%94%B1%5D%0A%20%20%20%20GW%20--%3E%20APP%5B%E5%BA%94%E7%94%A8%E5%B1%82%3Cbr%2F%3E%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%2F%E7%BA%BF%E7%A8%8B%E6%B1%A0%2F%E5%BC%82%E6%AD%A5%E5%8C%96%5D%0A%20%20%20%20APP%20--%3E%20CACHE%5B%E7%BC%93%E5%AD%98%E5%B1%82%20Redis%3Cbr%2F%3E%E6%89%9B%E4%BD%8F%E7%83%AD%E7%82%B9%E8%AF%BB%5D%0A%20%20%20%20CACHE%20--%3E%20DB%5B(%E6%95%B0%E6%8D%AE%E5%BA%93%E5%B1%82%3Cbr%2F%3E%E5%88%86%E5%BA%93%E5%88%86%E8%A1%A8%2F%E8%AF%BB%E5%86%99%E5%88%86%E7%A6%BB)%5D%0A%20%20%20%20APP%20-.%E5%BC%82%E6%AD%A5%E5%89%8A%E5%B3%B0.-%3E%20MQ%5B(%E6%B6%88%E6%81%AF%E9%98%9F%E5%88%97)%5D%0A%20%20%20%20MQ%20--%3E%20APP2%5B%E6%B6%88%E8%B4%B9%E7%AB%AF%E6%9C%8D%E5%8A%A1%3Cbr%2F%3E%E6%8C%89%E8%83%BD%E5%8A%9B%E5%8C%80%E9%80%9F%E6%B6%88%E8%B4%B9%5D%0A"})]),fallback:a(()=>t[0]||(t[0]=[o(" Loading... ")])),_:1})),t[5]||(t[5]=r('<h3 id="_2-2-各层职责与能力量级" tabindex="-1">2.2 各层职责与能力量级 <a class="header-anchor" href="#_2-2-各层职责与能力量级" aria-label="Permalink to &quot;2.2 各层职责与能力量级&quot;">​</a></h3><table><thead><tr><th>层</th><th>职责</th><th>单位成本</th><th>处理量级</th></tr></thead><tbody><tr><td>DNS/CDN</td><td>就近分发、静态内容卸载</td><td>极低</td><td>百万级 QPS</td></tr><tr><td>网关</td><td>限流、鉴权、路由，挡掉非法流量</td><td>低</td><td>万~十万 QPS</td></tr><tr><td>应用</td><td>业务逻辑、本地缓存、异步发送</td><td>中</td><td>千~万 QPS</td></tr><tr><td>缓存</td><td>热点数据扛读</td><td>低</td><td>十万级 QPS</td></tr><tr><td>数据库</td><td>最终一致性数据、写</td><td>高（最难扩展）</td><td>千级 QPS</td></tr></tbody></table><h3 id="_2-3-分层防护的三条原则" tabindex="-1">2.3 分层防护的三条原则 <a class="header-anchor" href="#_2-3-分层防护的三条原则" aria-label="Permalink to &quot;2.3 分层防护的三条原则&quot;">​</a></h3><ol><li><strong>能静态不动态</strong>：静态资源、可预生成的页面一律上 CDN；</li><li><strong>能缓存不查库</strong>：读请求优先在缓存层消化；</li><li><strong>能异步不阻塞</strong>：非即时结果走 MQ 削峰，让昂贵的写能力匀速运行。</li></ol><p>架构师在每一层都要问：这层能替我挡掉多少流量？如果流量全打到数据库，说明前面的层全都失职了。</p><hr><h2 id="三、读多写少与写多读少" tabindex="-1">三、读多写少与写多读少 <a class="header-anchor" href="#三、读多写少与写多读少" aria-label="Permalink to &quot;三、读多写少与写多读少&quot;">​</a></h2><h3 id="_3-1-读多写少场景-内容-商品-资讯类" tabindex="-1">3.1 读多写少场景（内容/商品/资讯类） <a class="header-anchor" href="#_3-1-读多写少场景-内容-商品-资讯类" aria-label="Permalink to &quot;3.1 读多写少场景（内容/商品/资讯类）&quot;">​</a></h3><p><strong>典型特征</strong>：读写比 10:1 以上，读有热点、可容忍短暂不一致。</p><p><strong>设计思路</strong>：</p><ol><li>缓存前置：详情/列表全部缓存，key 按业务聚合（见第四章）；</li><li>CDN 卸载：图片、静态页、预渲染结果上 CDN；</li><li>读模型专门化：复杂查询投影到宽表/搜索/缓存（参考 DDD 笔记的 CQRS）；</li><li>热点隔离：发现热点 key 自动本地缓存 + 多级缓存兜底（防击穿）。</li></ol><h3 id="_3-2-写多读少场景-日志、埋点、交易流水类" tabindex="-1">3.2 写多读少场景（日志、埋点、交易流水类） <a class="header-anchor" href="#_3-2-写多读少场景-日志、埋点、交易流水类" aria-label="Permalink to &quot;3.2 写多读少场景（日志、埋点、交易流水类）&quot;">​</a></h3><p><strong>典型特征</strong>：写入量大、读少但要求查询能力、写不能丢。</p><p><strong>设计思路</strong>：</p><ol><li><strong>批量与异步</strong>：写入先落本地/内存缓冲，攒批后批量刷库或发 MQ；</li><li><strong>顺序写</strong>：日志类数据用追加写模型（如消息队列落盘、LSM 存储），避免随机写；</li><li><strong>写入分片</strong>：按业务键哈希分库分表，分散单库写压力（决策见第七章）；</li><li><strong>读写分离</strong>：主库扛写，从库扛读与分析（延迟可容忍时）。</li></ol><h3 id="_3-3-两类场景设计对比表" tabindex="-1">3.3 两类场景设计对比表 <a class="header-anchor" href="#_3-3-两类场景设计对比表" aria-label="Permalink to &quot;3.3 两类场景设计对比表&quot;">​</a></h3><table><thead><tr><th>维度</th><th>读多写少</th><th>写多读少</th></tr></thead><tbody><tr><td>主要矛盾</td><td>读放大、热点</td><td>写放大、单点写瓶颈</td></tr><tr><td>首要手段</td><td>缓存 + CDN</td><td>异步批量 + 分片</td></tr><tr><td>一致性要求</td><td>可容忍短暂不一致</td><td>写不能丢（可靠性优先）</td></tr><tr><td>数据库策略</td><td>缓存扛读，DB 兜底</td><td>分库分表 + 读写分离</td></tr><tr><td>典型例子</td><td>商品详情、资讯 Feed</td><td>埋点、订单流水、IM 消息</td></tr></tbody></table><p>现实中多数业务是<strong>混合型</strong>（如电商：商品详情读多写少、库存/订单写多读少），正确做法是给不同能力分别设计，而不是一套方案走天下。</p><hr><h2 id="四、缓存体系设计" tabindex="-1">四、缓存体系设计 <a class="header-anchor" href="#四、缓存体系设计" aria-label="Permalink to &quot;四、缓存体系设计&quot;">​</a></h2><h3 id="_4-1-缓存分层" tabindex="-1">4.1 缓存分层 <a class="header-anchor" href="#_4-1-缓存分层" aria-label="Permalink to &quot;4.1 缓存分层&quot;">​</a></h3><table><thead><tr><th>层</th><th>代表</th><th>适用</th><th>容量/时效</th></tr></thead><tbody><tr><td>客户端缓存</td><td>浏览器 Cache、App 本地</td><td>静态与弱变资源</td><td>由 HTTP 头控制</td></tr><tr><td>CDN</td><td>边缘节点</td><td>静态/半静态内容</td><td>分钟~小时级</td></tr><tr><td>本地缓存</td><td>Caffeine/Guava</td><td>热点 key、JVM 内</td><td>秒级，需失效同步</td></tr><tr><td>分布式缓存</td><td>Redis</td><td>全局共享热点读</td><td>由 TTL 控制</td></tr><tr><td>数据库缓存</td><td>MySQL Buffer Pool</td><td>引擎内部</td><td>自动</td></tr></tbody></table><p><strong>两级缓存策略</strong>（本地 + Redis）是应对&quot;热点 key 打爆 Redis&quot;的常见组合：本地缓存挡 90% 的同类请求，Redis 兜底。但本地缓存一致性最弱，适合变更不频繁的热数据；变更频繁的数据只放 Redis。</p><h3 id="_4-2-缓存一致性" tabindex="-1">4.2 缓存一致性 <a class="header-anchor" href="#_4-2-缓存一致性" aria-label="Permalink to &quot;4.2 缓存一致性&quot;">​</a></h3><p>缓存与数据库双写的一致性本质是&quot;先写库还是先删缓存&quot;的选择：</p><table><thead><tr><th>策略</th><th>过程</th><th>问题</th></tr></thead><tbody><tr><td>先更新库再删缓存</td><td>写库 → 删缓存</td><td>删除失败会留下脏缓存（可用延迟双删兜底）</td></tr><tr><td>先删缓存再更新库</td><td>删缓存 → 写库</td><td>写库期间旧值可能被并发重新入缓存</td></tr><tr><td>Cache Aside + 订阅 binlog 删缓存</td><td>业务只写库，删缓存由订阅程序做</td><td>最稳，适合一致性敏感的写</td></tr></tbody></table><p><strong>务实结论</strong>：绝大多数读多写少场景能容忍秒级不一致，采用&quot;先写库，后删缓存&quot; + TTL 兜底即可；追求更强一致性时用&quot;订阅 binlog 异步删缓存&quot;，不要为缓存一致性引入分布式事务（那是过度设计）。</p><h3 id="_4-3-缓存三大问题与对策" tabindex="-1">4.3 缓存三大问题与对策 <a class="header-anchor" href="#_4-3-缓存三大问题与对策" aria-label="Permalink to &quot;4.3 缓存三大问题与对策&quot;">​</a></h3><table><thead><tr><th>问题</th><th>现象</th><th>对策</th></tr></thead><tbody><tr><td>穿透</td><td>查不存在的 key，每次打到 DB</td><td>缓存空值（短 TTL）；布隆过滤器拦截；接口层参数校验</td></tr><tr><td>击穿</td><td>单个热点 key 过期瞬间并发打到 DB</td><td>互斥重建（只允许一个线程查库回填）；逻辑过期 + 异步刷新；热点 key 永不过期+主动更新</td></tr><tr><td>雪崩</td><td>大量 key 同时过期</td><td>过期时间加随机抖动；多级缓存；缓存集群高可用（哨兵/Cluster）</td></tr></tbody></table><h3 id="_4-4-缓存容量与淘汰策略" tabindex="-1">4.4 缓存容量与淘汰策略 <a class="header-anchor" href="#_4-4-缓存容量与淘汰策略" aria-label="Permalink to &quot;4.4 缓存容量与淘汰策略&quot;">​</a></h3><ul><li>单 key 过大（&gt;10KB 的热点）会造成带宽压力，大对象拆分为多个 key 或压缩；</li><li>内存淘汰策略：绝大多数业务用 <code>allkeys-lru</code> / <code>volatile-lru</code>；<strong><code>noeviction</code>（不淘汰）绝不可用于生产</strong>，会直接写失败；</li><li>容量监控：以内存使用率 + 命中率 + 逐出量三指标盯缓存健康。</li></ul><h3 id="_4-5-缓存设计决策树" tabindex="-1">4.5 缓存设计决策树 <a class="header-anchor" href="#_4-5-缓存设计决策树" aria-label="Permalink to &quot;4.5 缓存设计决策树&quot;">​</a></h3>',32)),(e(),s(n,null,{default:a(()=>[d(l,{id:"mermaid-721",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%95%B0%E6%8D%AE%E5%8F%98%E5%8C%96%E9%A2%91%E7%8E%87%3F%5D%20--%3E%7C%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%7C%20B%5BCDN%2F%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%E9%95%BF%20TTL%5D%0A%20%20%20%20A%20--%3E%7C%E4%BD%8E%E9%A2%91%E5%8F%98%E6%9B%B4%7C%20C%5BRedis%20%2B%20TTL%2010min~1h%3Cbr%2F%3ECache%20Aside%5D%0A%20%20%20%20A%20--%3E%7C%E9%AB%98%E9%A2%91%E5%8F%98%E6%9B%B4%7C%20D%5BRedis%20%2B%20%E7%9F%AD%20TTL%20%E6%88%96%E6%B6%88%E6%81%AF%E4%B8%BB%E5%8A%A8%E5%A4%B1%E6%95%88%5D%0A%20%20%20%20A%20--%3E%7C%E5%BC%BA%E4%B8%80%E8%87%B4%E8%A6%81%E6%B1%82%7C%20E%5B%E5%86%99%E5%BA%93%20%2B%20binlog%20%E8%AE%A2%E9%98%85%E5%88%A0%E7%BC%93%E5%AD%98%3Cbr%2F%3E%E4%B8%8D%E7%94%A8%E5%88%86%E5%B8%83%E5%BC%8F%E4%BA%8B%E5%8A%A1%5D%0A%20%20%20%20C%20--%3E%20F%7B%E7%83%AD%E7%82%B9%20key%3F%7D%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20F%20--%3E%7C%E6%98%AF%7C%20G%5B%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%20%2B%20%E4%BA%92%E6%96%A5%E9%87%8D%E5%BB%BA%3Cbr%2F%3E%E9%98%B2%E5%87%BB%E7%A9%BF%5D%0A%20%20%20%20F%20--%3E%7C%E5%90%A6%7C%20H%5B%E5%B8%B8%E8%A7%84%E8%AE%BE%E8%AE%A1%E5%8D%B3%E5%8F%AF%5D%0A%20%20%20%20E%20--%3E%20F%0A"})]),fallback:a(()=>t[1]||(t[1]=[o(" Loading... ")])),_:1})),t[6]||(t[6]=r(`<hr><h2 id="五、异步化" tabindex="-1">五、异步化 <a class="header-anchor" href="#五、异步化" aria-label="Permalink to &quot;五、异步化&quot;">​</a></h2><h3 id="_5-1-异步化的三个目的" tabindex="-1">5.1 异步化的三个目的 <a class="header-anchor" href="#_5-1-异步化的三个目的" aria-label="Permalink to &quot;5.1 异步化的三个目的&quot;">​</a></h3><ol><li><strong>削峰填谷</strong>：瞬时高峰落 MQ，消费端匀速处理，保护数据库与下游；</li><li><strong>降低 RT</strong>：非即时步骤（发短信、算积分）从同步链路摘除，主链路更快返回；</li><li><strong>解耦</strong>：核心流程只发事件，扩展方订阅（与 DDD 领域事件天然配合）。</li></ol><h3 id="_5-2-mq-削峰" tabindex="-1">5.2 MQ 削峰 <a class="header-anchor" href="#_5-2-mq-削峰" aria-label="Permalink to &quot;5.2 MQ 削峰&quot;">​</a></h3><p>经典模型：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">流量高峰 10 万 TPS 请求</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 网关限流只放 1 万 TPS 进系统</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 请求落 MQ（MQ 本身可扛百万级 TPS 写入）</span></span>
<span class="line"><span style="color:#e1e4e8;">  → 消费端按 DB 能力（如 2000 TPS）匀速消费</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">流量高峰 10 万 TPS 请求</span></span>
<span class="line"><span style="color:#24292e;">  → 网关限流只放 1 万 TPS 进系统</span></span>
<span class="line"><span style="color:#24292e;">  → 请求落 MQ（MQ 本身可扛百万级 TPS 写入）</span></span>
<span class="line"><span style="color:#24292e;">  → 消费端按 DB 能力（如 2000 TPS）匀速消费</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>要点：削峰不是无限缓冲——要配套<strong>消息积压监控</strong>与<strong>消费端水平扩容</strong>，并明确&quot;积压超过 X 分钟触发告警/扩容&quot;的预案。消息可靠性与消费幂等设计见《微服务架构与拆分》第二章。</p><h3 id="_5-3-批量与合并请求" tabindex="-1">5.3 批量与合并请求 <a class="header-anchor" href="#_5-3-批量与合并请求" aria-label="Permalink to &quot;5.3 批量与合并请求&quot;">​</a></h3><ul><li><strong>批量写</strong>：攒批刷库（如每 500ms 或 500 条刷一次），显著提升吞吐；埋点/日志类数据标配；</li><li><strong>合并请求（Coalescing）</strong>：同一资源的并发读合并为一个上游请求（JVM 内单 flight 请求），缓存击穿时保护下游；</li><li><strong>批量拉取</strong>：循环里单查改为批量查（IN 查询），消除 N+1。</li></ul><h3 id="_5-4-异步化引入的新问题" tabindex="-1">5.4 异步化引入的新问题 <a class="header-anchor" href="#_5-4-异步化引入的新问题" aria-label="Permalink to &quot;5.4 异步化引入的新问题&quot;">​</a></h3><table><thead><tr><th>新问题</th><th>对策</th></tr></thead><tbody><tr><td>消息丢失</td><td>生产端确认、消费端手动 ack、本地消息表兜底</td></tr><tr><td>消息重复</td><td>消费幂等（业务键去重表/唯一索引）</td></tr><tr><td>消息积压</td><td>积压监控 + 队列扩容 + 临时加消费者</td></tr><tr><td>调试困难</td><td>消息体带 Trace ID，贯穿日志链路</td></tr><tr><td>数据延迟可见</td><td>对延迟敏感页面做&quot;状态提示 + 主动刷新&quot;</td></tr></tbody></table><p>异步化把&quot;实时问题&quot;变成了&quot;延迟 + 可靠性问题&quot;，<strong>必须配套消费监控与对账</strong>才能上生产。</p><hr><h2 id="六、隔离-熔断-降级-限流" tabindex="-1">六、隔离 / 熔断 / 降级 / 限流 <a class="header-anchor" href="#六、隔离-熔断-降级-限流" aria-label="Permalink to &quot;六、隔离 / 熔断 / 降级 / 限流&quot;">​</a></h2><h3 id="_6-1-四种策略的定位" tabindex="-1">6.1 四种策略的定位 <a class="header-anchor" href="#_6-1-四种策略的定位" aria-label="Permalink to &quot;6.1 四种策略的定位&quot;">​</a></h3><table><thead><tr><th>策略</th><th>保护谁</th><th>核心动作</th><th>触发依据</th></tr></thead><tbody><tr><td>隔离</td><td>故障方与正常方</td><td>物理/逻辑分舱，互不拖垮</td><td>按资源/依赖预规划</td></tr><tr><td>熔断</td><td>调用方</td><td>快速失败，停止调用故障依赖</td><td>错误率/慢调用达到阈值</td></tr><tr><td>降级</td><td>整体可用性</td><td>牺牲非核心功能保核心</td><td>人工预案/自动条件</td></tr><tr><td>限流</td><td>系统容量</td><td>拒绝超额请求</td><td>QPS/并发数阈值</td></tr></tbody></table><p>一句话：<strong>隔离是分舱（预防），熔断是切断（对故障依赖），降级是取舍（保核心弃边缘），限流是闸门（防超载）</strong>。</p><h3 id="_6-2-隔离" tabindex="-1">6.2 隔离 <a class="header-anchor" href="#_6-2-隔离" aria-label="Permalink to &quot;6.2 隔离&quot;">​</a></h3><ul><li><strong>线程池隔离</strong>：不同依赖用独立线程池（如 Hystrix 模式），某依赖占满线程池不影响其它；代价是线程开销大，适合依赖少的场景；</li><li><strong>信号量隔离</strong>：限制并发数而非独立线程，轻量、适合快速失败场景；</li><li><strong>物理隔离</strong>：热点业务独立集群/独立数据库实例，如&quot;秒杀单独部署&quot;，故障半径最小；</li><li><strong>动静/读写隔离</strong>：读服务与写服务分离，管理端与交易端分离，互相不拖累。</li></ul><h3 id="_6-3-熔断" tabindex="-1">6.3 熔断 <a class="header-anchor" href="#_6-3-熔断" aria-label="Permalink to &quot;6.3 熔断&quot;">​</a></h3><ul><li><strong>三态</strong>：关闭（Closed）→ 打开（Open）→ 半开（Half-Open）。错误率超阈值熔断打开，此时请求快速失败；经过冷却窗口进入半开，放少量探测流量，成功则关闭、失败则重新打开；</li><li><strong>关键参数</strong>：错误率阈值（如 50%）、最小调用量（避免少量流量误触发）、冷却时长、半开探测请求数；</li><li><strong>注意</strong>：熔断打开的&quot;快速失败&quot;只是止损，真正的恢复依赖下游自愈 + 上游降级兜底；</li><li>实现见《SpringCloud微服务》笔记的 Sentinel/Resilience4j。</li></ul><h3 id="_6-4-降级" tabindex="-1">6.4 降级 <a class="header-anchor" href="#_6-4-降级" aria-label="Permalink to &quot;6.4 降级&quot;">​</a></h3><ul><li><strong>分级降级</strong>：把功能分成核心（必须保）/非核心（可牺牲）两级，压力大时关闭非核心（如关闭个性化推荐，只出通用列表）；</li><li><strong>降级预案</strong>：每个关键依赖提前写好降级开关（配置中心一键切换），如缓存故障 → 直连 DB（限流配合）、推荐故障 → 返回兜底列表；</li><li><strong>返回降级</strong>：查询失败返回旧缓存数据（stale 兜底）而非报错；</li><li>降级必须有<strong>自动化触发 + 人工确认</strong>双通道，并记录降级时段用于复盘。</li></ul><h3 id="_6-5-限流" tabindex="-1">6.5 限流 <a class="header-anchor" href="#_6-5-限流" aria-label="Permalink to &quot;6.5 限流&quot;">​</a></h3><ul><li><strong>维度</strong>：单机 QPS、集群 QPS、并发线程数、用户/IP 维度限流；</li><li><strong>位置</strong>：网关层（全局限流）+ 应用层（接口/用户级限流）两级配合；</li><li><strong>算法对比</strong>见《经典系统设计案例》附表的限流算法对比表；</li><li><strong>限流拒绝语义</strong>：排队等待（削峰）或直接快速失败（返回 429/友好提示），业务按需选择。</li></ul><h3 id="_6-6-四策略联动与指标监控" tabindex="-1">6.6 四策略联动与指标监控 <a class="header-anchor" href="#_6-6-四策略联动与指标监控" aria-label="Permalink to &quot;6.6 四策略联动与指标监控&quot;">​</a></h3>`,27)),(e(),s(n,null,{default:a(()=>[d(l,{id:"mermaid-1025",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E6%B5%81%E9%87%8F%E7%AA%81%E5%A2%9E%5D%20--%3E%20B%5B%E7%BD%91%E5%85%B3%E9%99%90%E6%B5%81%3Cbr%2F%3E%E6%8B%A6%E8%B6%85%E8%BD%BD%5D%0A%20%20%20%20A%20--%3E%20C%7B%E4%B8%8B%E6%B8%B8%E4%BE%9D%E8%B5%96%E6%95%85%E9%9A%9C%3F%7D%0A%20%20%20%20C%20--%3E%7C%E6%98%AF%7C%20D%5B%E7%86%94%E6%96%AD%E6%89%93%E5%BC%80%5D%0A%20%20%20%20D%20--%3E%20E%5B%E9%99%8D%E7%BA%A7%E9%A2%84%E6%A1%88%3Cbr%2F%3E%E8%BF%94%E5%9B%9E%E5%85%9C%E5%BA%95%2F%E7%A6%81%E7%94%A8%E9%9D%9E%E6%A0%B8%E5%BF%83%5D%0A%20%20%20%20C%20--%3E%7C%E5%90%A6%7C%20F%5B%E9%9A%94%E7%A6%BB%E8%88%B1%E6%AD%A3%E5%B8%B8%E6%89%BF%E8%BD%BD%5D%0A"})]),fallback:a(()=>t[2]||(t[2]=[o(" Loading... ")])),_:1})),t[7]||(t[7]=r('<table><thead><tr><th>策略</th><th>关键指标</th><th>告警建议</th></tr></thead><tbody><tr><td>隔离</td><td>各舱线程池活跃度、队列深度</td><td>队列占用 &gt; 70% 持续 1 分钟</td></tr><tr><td>熔断</td><td>错误率、熔断打开次数、快速失败量</td><td>熔断打开即告警</td></tr><tr><td>降级</td><td>降级开关状态、降级请求占比</td><td>自动降级触发即告警</td></tr><tr><td>限流</td><td>被限 QPS、限流占比</td><td>限流占比 &gt; 20% 持续 5 分钟</td></tr></tbody></table><p><strong>取舍顺序</strong>：资源紧张时依次执行&quot;限流挡外部 → 熔断切故障依赖 → 降级舍非核心 → 隔离保舱内核心&quot;，目标始终是让<strong>核心链路的成功率</strong>最高。</p><hr><h2 id="七、数据库层设计" tabindex="-1">七、数据库层设计 <a class="header-anchor" href="#七、数据库层设计" aria-label="Permalink to &quot;七、数据库层设计&quot;">​</a></h2><h3 id="_7-1-索引先行" tabindex="-1">7.1 索引先行 <a class="header-anchor" href="#_7-1-索引先行" aria-label="Permalink to &quot;7.1 索引先行&quot;">​</a></h3><p>数据库层的第一步不是分库分表而是<strong>索引优化</strong>（原理与优化细则见《MySQL深入》笔记），因为索引优化的成本远低于架构拆分：</p><ul><li>慢查询治理：慢日志 + 执行计划分析（<code>EXPLAIN</code>）常态化；</li><li>联合索引按&quot;等值优先、排序次之&quot;设计，覆盖索引消除回表；</li><li>索引失效场景（函数操作、隐式类型转换、左模糊）纳入代码评审；</li><li>单表数据量在千万级以内、读写可控时，<strong>索引足够就不必分表</strong>。</li></ul><h3 id="_7-2-读写分离" tabindex="-1">7.2 读写分离 <a class="header-anchor" href="#_7-2-读写分离" aria-label="Permalink to &quot;7.2 读写分离&quot;">​</a></h3><ul><li><strong>适用</strong>：读远大于写（读多写少），从库扛读查询与分析；</li><li><strong>架构</strong>：主库写 + 从库读，中间件（如 ShardingSphere/MyCat）或应用层路由；</li><li><strong>代价</strong>：主从延迟导致&quot;写后读不一致&quot;——对策：刚写的数据强制走主库、关键读走主库、可容忍延迟的读走从库；</li><li><strong>局限</strong>：读写分离不解决写瓶颈，写放大时才需要分库分表。</li></ul><h3 id="_7-3-分库分表决策树" tabindex="-1">7.3 分库分表决策树 <a class="header-anchor" href="#_7-3-分库分表决策树" aria-label="Permalink to &quot;7.3 分库分表决策树&quot;">​</a></h3>',10)),(e(),s(n,null,{default:a(()=>[d(l,{id:"mermaid-1150",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E5%8D%95%E8%A1%A8%E6%95%B0%E6%8D%AE%E9%87%8F%20%3E%20%E5%8D%83%E4%B8%87%E7%BA%A7%E6%88%96%3Cbr%2F%3E%E5%8D%95%E5%BA%93%E5%86%99%E5%85%A5%E6%88%90%E7%93%B6%E9%A2%88%3F%5D%20--%3E%7C%E5%90%A6%7C%20B%5B%E4%BF%9D%E6%8C%81%E5%8D%95%E5%BA%93%E5%8D%95%E8%A1%A8%3Cbr%2F%3E%E4%BC%98%E5%8C%96%E7%B4%A2%E5%BC%95%E5%8D%B3%E5%8F%AF%5D%0A%20%20%20%20A%20--%3E%7C%E6%98%AF%7C%20C%7B%E7%93%B6%E9%A2%88%E6%98%AF%E8%AF%BB%E8%BF%98%E6%98%AF%E5%86%99%3F%7D%0A%20%20%20%20C%20--%3E%7C%E8%AF%BB%E4%B8%BA%E4%B8%BB%7C%20D%7B%E8%AF%BB%E6%94%BE%E5%A4%A7%E8%83%BD%E5%90%A6%E7%94%A8%E7%BC%93%E5%AD%98%2F%E4%BB%8E%E5%BA%93%E6%B6%88%E5%8C%96%3F%7D%0A%20%20%20%20D%20--%3E%7C%E8%83%BD%7C%20E%5B%E7%BC%93%E5%AD%98%20%2B%20%E8%AF%BB%E5%86%99%E5%88%86%E7%A6%BB%3Cbr%2F%3E%E6%9A%82%E4%B8%8D%E5%88%86%E8%A1%A8%5D%0A%20%20%20%20D%20--%3E%7C%E4%B8%8D%E8%83%BD%7C%20F%5B%E5%88%86%E8%A1%A8%3A%E6%8C%89%E4%B8%9A%E5%8A%A1%E9%94%AE%E6%B0%B4%E5%B9%B3%E5%88%86%E8%A1%A8%3Cbr%2F%3E%E5%BF%85%E8%A6%81%E6%97%B6%E5%88%86%E5%BA%93%5D%0A%20%20%20%20C%20--%3E%7C%E5%86%99%E4%B8%BA%E4%B8%BB%7C%20G%5B%E5%88%86%E5%BA%93%3A%E6%8C%89%E4%B8%9A%E5%8A%A1%E9%94%AE%E5%93%88%E5%B8%8C%2F%E8%8C%83%E5%9B%B4%E5%88%86%E5%BA%93%5D%0A%20%20%20%20F%20--%3E%20H%5B%E5%90%8C%E6%97%B6%E8%80%83%E8%99%91%3A%E5%88%86%E7%89%87%E9%94%AE%E9%80%89%E6%8B%A9%3Cbr%2F%3E%E5%85%A8%E5%B1%80%E5%94%AF%E4%B8%80ID%2F%E8%B7%A8%E5%88%86%E7%89%87%E6%9F%A5%E8%AF%A2%2F%E6%89%A9%E5%AE%B9%5D%0A%20%20%20%20G%20--%3E%20H%0A"})]),fallback:a(()=>t[3]||(t[3]=[o(" Loading... ")])),_:1})),t[8]||(t[8]=r('<p><strong>决策要点</strong>：</p><ol><li><strong>分片键（Sharding Key）是分库分表的灵魂</strong>：必须按最高频查询路由，如订单按 <code>user_id</code> 分片、订单明细与订单同片（避免跨片 join 与事务）；</li><li>分库分表无法回避的三件事：跨分片查询（汇总层/宽表/ES 兜底）、分布式 ID（见《经典系统设计案例》附表）、数据迁移与扩容（一致性哈希 + 虚拟节点 / 双写迁移）；</li><li>事务边界收窄到单分片内，跨分片事务用最终一致性（见《微服务架构与拆分》第六章）；</li><li>先垂直拆分（按业务拆库）再水平分表，不要一上来就水平分 64 表。</li></ol><h3 id="_7-4-详版指引" tabindex="-1">7.4 详版指引 <a class="header-anchor" href="#_7-4-详版指引" aria-label="Permalink to &quot;7.4 详版指引&quot;">​</a></h3><p>分库分表与读写分离的完整实现细则（分片策略、中间件配置、迁移方案）详见<a href="./../../database/MySQL深入">《MySQL深入》分库分表章节</a>，本笔记只保留决策树与方法论。判断口诀：<strong>先索引，再缓存，后读写分离，最后才是分库分表</strong>——越靠后的手段成本越高、越不可逆。</p><hr><h2 id="八、高并发系统设计通用-8-步法" tabindex="-1">八、高并发系统设计通用 8 步法 <a class="header-anchor" href="#八、高并发系统设计通用-8-步法" aria-label="Permalink to &quot;八、高并发系统设计通用 8 步法&quot;">​</a></h2><h3 id="_8-1-8-步总览" tabindex="-1">8.1 8 步总览 <a class="header-anchor" href="#_8-1-8-步总览" aria-label="Permalink to &quot;8.1 8 步总览&quot;">​</a></h3><ol><li>明确场景与指标 → 2. 估算容量 → 3. 画分层架构 → 4. 设计缓存 → 5. 异步化 → 6. 保护策略 → 7. 数据库方案 → 8. 兜底与监控。口诀：&quot;<strong>场景指标、容量分层、缓存异步、保护分库、兜底监控</strong>&quot;。</li></ol><h3 id="_8-2-分步详解" tabindex="-1">8.2 分步详解 <a class="header-anchor" href="#_8-2-分步详解" aria-label="Permalink to &quot;8.2 分步详解&quot;">​</a></h3><p><strong>步骤一：明确场景与指标</strong></p><ul><li>回答：这是读多还是写多？数据规模多大？一致性要求多高？</li><li>定指标：目标 QPS、可用性（如 99.99%）、RT（P99 &lt; 200ms）、数据量（总量 + 增速）。</li></ul><p><strong>步骤二：容量评估</strong></p><ul><li>按第一章公式估平均/峰值 QPS，推实例数与资源（中间件规格、带宽），并评估&quot;峰值多少能削&quot;。</li></ul><p><strong>步骤三：分层架构</strong></p><ul><li>按第二章六层模型画图：哪些流量在 CDN/缓存消化、哪些必须实时、哪些走异步。</li></ul><p><strong>步骤四：设计缓存</strong></p><ul><li>按第四章决策树定缓存层级、TTL、一致性与热点防护（穿透/击穿/雪崩三件套）。</li></ul><p><strong>步骤五：异步化</strong></p><ul><li>非即时步骤摘出主链路，MQ 削峰，明确消费能力、积压预案与幂等设计。</li></ul><p><strong>步骤六：保护策略</strong></p><ul><li>按第六章对关键依赖做隔离 + 熔断 + 降级预案，全局限流（网关）+ 应用限流。</li></ul><p><strong>步骤七：数据库方案</strong></p><ul><li>按第七章决策树：索引治理 → 读写分离 → 分库分表，明确分片键与分布式 ID。</li></ul><p><strong>步骤八：兜底与监控</strong></p><ul><li>全链路 Trace、核心指标大盘（QPS/RT/错误率/缓存命中率/积压量）、容量告警、压测与预案演练（大促前全链路压测 + 故障演练）。</li></ul><h3 id="_8-3-一个-通用电商查询页-的-8-步速成示例" tabindex="-1">8.3 一个&quot;通用电商查询页&quot;的 8 步速成示例 <a class="header-anchor" href="#_8-3-一个-通用电商查询页-的-8-步速成示例" aria-label="Permalink to &quot;8.3 一个&quot;通用电商查询页&quot;的 8 步速成示例&quot;">​</a></h3><table><thead><tr><th>步骤</th><th>决策</th></tr></thead><tbody><tr><td>1 指标</td><td>峰值 5 万 QPS 读详情，P99&lt;200ms，容忍 1s 缓存不一致</td></tr><tr><td>2 容量</td><td>单机 1500 QPS，需 ~43 台；但缓存后实际打 DB 仅 2%</td></tr><tr><td>3 分层</td><td>CDN(静态) → 网关限流 → 应用(本地缓存) → Redis → DB</td></tr><tr><td>4 缓存</td><td>详情 key TTL 10min + 随机抖动；热点商品本地缓存 + 互斥重建</td></tr><tr><td>5 异步</td><td>浏览计数、足迹记录走 MQ，不阻塞主读链路</td></tr><tr><td>6 保护</td><td>网关按用户限流；Redis 故障时降级直连 DB(限流降 QPS)</td></tr><tr><td>7 数据库</td><td>单表千万级内保持单表 + 从库扛报表查询</td></tr><tr><td>8 监控</td><td>命中率 &lt; 90% 告警，RT 突增告警，大促前全链路压测</td></tr></tbody></table><h3 id="_8-4-自查清单" tabindex="-1">8.4 自查清单 <a class="header-anchor" href="#_8-4-自查清单" aria-label="Permalink to &quot;8.4 自查清单&quot;">​</a></h3><ul><li>[ ] 容量有数字依据（估算 + 压测），不是拍脑袋；</li><li>[ ] 每条读链路都回答了&quot;缓存怎么设计、热点怎么防&quot;；</li><li>[ ] 每条写链路都回答了&quot;峰值怎么削、消息怎么不丢不重&quot;；</li><li>[ ] 每个外部依赖都有超时 + 熔断 + 降级预案；</li><li>[ ] 数据库方案遵循&quot;索引 → 缓存 → 读写分离 → 分库分表&quot;顺序；</li><li>[ ] 有监控大盘、告警阈值与故障演练记录。</li></ul>',29))])}const C=i(p,[["render",B]]);export{D as __pageData,C as default};
